using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Enums; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Areas.Admin.Pages; [Authorize(Policy="SuperAdmin")] public class DashboardModel:PageModel{private readonly OrcaFacilDbContext _db; public int TotalUsers{get;private set;} public int TotalDocuments{get;private set;} public int FreeUsers{get;private set;} public int ProUsers{get;private set;} public DashboardModel(OrcaFacilDbContext db)=>_db=db; public async Task OnGetAsync(){TotalUsers=await _db.Users.CountAsync(); TotalDocuments=await _db.Documents.CountAsync(); FreeUsers=await _db.Users.CountAsync(u=>u.Plan==PlanType.Free); ProUsers=await _db.Users.CountAsync(u=>u.Plan==PlanType.Pro);}}
